//! Anti-aliased proportional text from an `OSXP` atlas (generated by
//! `scripts/gen-ui-fonts.py`): per-glyph bitmaps with bearings and
//! advances, looked up by code point.

use crate::text::{read_u32, AssetError};
use crate::{Color, Rect, Surface};

const HEADER: usize = 20;
const RECORD: usize = 16;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Glyph<'a> {
    pub left: i32,
    pub top: i32,
    pub width: u32,
    pub height: u32,
    pub advance: u32,
    pub coverage: &'a [u8],
}

#[derive(Clone, Copy)]
pub struct PropFont<'a> {
    line_height: u32,
    ascent: u32,
    count: usize,
    records: &'a [u8],
    offsets: &'a [u8],
    coverage: &'a [u8],
}

impl<'a> PropFont<'a> {
    pub fn parse(bytes: &'a [u8]) -> Result<Self, AssetError> {
        if bytes.get(0..4) != Some(b"OSXP") {
            return Err(AssetError::BadMagic);
        }
        if read_u32(bytes, 4)? != 1 {
            return Err(AssetError::BadDimensions);
        }
        let line_height = read_u32(bytes, 8)?;
        let ascent = read_u32(bytes, 12)?;
        let count = read_u32(bytes, 16)? as usize;
        if count == 0 || count > 65536 || line_height == 0 || line_height > 512 || ascent > line_height {
            return Err(AssetError::BadDimensions);
        }
        let rec_end = HEADER + count * RECORD;
        let off_end = rec_end + count * 4;
        let records = bytes.get(HEADER..rec_end).ok_or(AssetError::Truncated)?;
        let offsets = bytes.get(rec_end..off_end).ok_or(AssetError::Truncated)?;
        let coverage = bytes.get(off_end..).ok_or(AssetError::Truncated)?;
        let f = PropFont { line_height, ascent, count, records, offsets, coverage };
        // Every glyph's bitmap must lie inside the coverage block, and code
        // points must be strictly increasing (binary search relies on it).
        let mut prev = None;
        for i in 0..count {
            let cp = f.codepoint(i);
            if prev.is_some_and(|p| p >= cp) {
                return Err(AssetError::BadDimensions);
            }
            prev = Some(cp);
            let (w, h) = (f.u16_at(i, 8) as usize, f.u16_at(i, 10) as usize);
            let off = read_u32(offsets, i * 4)? as usize;
            if off.checked_add(w * h).is_none_or(|end| end > coverage.len()) {
                return Err(AssetError::Truncated);
            }
        }
        if f.index_of('?').is_none() {
            return Err(AssetError::BadDimensions);
        }
        Ok(f)
    }

    fn u16_at(&self, i: usize, off: usize) -> u16 {
        let b = &self.records[i * RECORD + off..];
        u16::from_le_bytes([b[0], b[1]])
    }

    fn codepoint(&self, i: usize) -> u32 {
        let b = &self.records[i * RECORD..];
        u32::from_le_bytes([b[0], b[1], b[2], b[3]])
    }

    fn index_of(&self, ch: char) -> Option<usize> {
        let target = ch as u32;
        let (mut lo, mut hi) = (0, self.count);
        while lo < hi {
            let mid = (lo + hi) / 2;
            match self.codepoint(mid).cmp(&target) {
                core::cmp::Ordering::Less => lo = mid + 1,
                core::cmp::Ordering::Greater => hi = mid,
                core::cmp::Ordering::Equal => return Some(mid),
            }
        }
        None
    }

    pub fn has(&self, ch: char) -> bool {
        self.index_of(ch).is_some()
    }

    /// The glyph for `ch`; characters the atlas lacks render as '?'.
    pub fn glyph(&self, ch: char) -> Glyph<'a> {
        let i = self.index_of(ch).or_else(|| self.index_of('?')).expect("'?' checked in parse");
        let w = self.u16_at(i, 8) as u32;
        let h = self.u16_at(i, 10) as u32;
        let off = u32::from_le_bytes([
            self.offsets[i * 4],
            self.offsets[i * 4 + 1],
            self.offsets[i * 4 + 2],
            self.offsets[i * 4 + 3],
        ]) as usize;
        Glyph {
            left: self.u16_at(i, 4) as i16 as i32,
            top: self.u16_at(i, 6) as i16 as i32,
            width: w,
            height: h,
            advance: self.u16_at(i, 12) as u32,
            coverage: &self.coverage[off..off + (w * h) as usize],
        }
    }

    pub fn line_height(&self) -> u32 {
        self.line_height
    }

    pub fn ascent(&self) -> u32 {
        self.ascent
    }

    pub fn advance(&self, ch: char) -> u32 {
        if ch == '\t' {
            return self.glyph(' ').advance * 4;
        }
        self.glyph(ch).advance
    }

    /// Width in pixels of `text`.
    pub fn measure(&self, text: &str) -> u32 {
        text.chars().map(|c| self.advance(c)).sum()
    }

    /// Byte index in `text` of the character boundary closest to pixel
    /// offset `x` (for placing a text cursor under the pointer).
    pub fn hit(&self, text: &str, x: i32) -> usize {
        let mut pen = 0i32;
        for (i, c) in text.char_indices() {
            let a = self.advance(c) as i32;
            if x < pen + a / 2 {
                return i;
            }
            pen += a;
        }
        text.len()
    }

    /// The longest prefix of `text` that fits `max` pixels including an
    /// ellipsis, or the whole text if it fits.
    pub fn ellipsize<'t>(&self, text: &'t str, max: u32) -> (&'t str, bool) {
        if self.measure(text) <= max {
            return (text, false);
        }
        let budget = max.saturating_sub(self.advance('…'));
        let mut w = 0;
        for (i, c) in text.char_indices() {
            w += self.advance(c);
            if w > budget {
                return (&text[..i], true);
            }
        }
        (text, false)
    }

    /// Draws `text` with the top of its line at (`x`, `y`), clipped to
    /// `clip` (and the surface). Returns the touched rectangle.
    #[allow(clippy::too_many_arguments)]
    pub fn draw_clipped(&self, s: &mut Surface, x: i32, y: i32, text: &str, c: Color, alpha: u32, clip: Rect) -> Rect {
        let clip = clip.intersect(&s.bounds());
        let mut pen = x;
        for ch in text.chars() {
            if ch == '\t' {
                pen = pen.saturating_add(self.advance('\t') as i32);
                continue;
            }
            let g = self.glyph(ch);
            let gx = pen.saturating_add(g.left);
            let gy = y.saturating_add(g.top);
            let area = Rect::new(gx, gy, g.width, g.height).intersect(&clip);
            if !area.is_empty() {
                for py in area.y..area.y + area.h as i32 {
                    let row = ((py - gy) as u32 * g.width) as usize;
                    for px in area.x..area.x + area.w as i32 {
                        let cov = g.coverage[row + (px - gx) as usize] as u32;
                        if cov != 0 {
                            s.blend_px(px, py, c, (cov * alpha + 127) / 255);
                        }
                    }
                }
            }
            pen = pen.saturating_add(g.advance as i32);
        }
        Rect::new(x, y, (pen as i64 - x as i64).clamp(0, u32::MAX as i64) as u32, self.line_height)
    }

    pub fn draw(&self, s: &mut Surface, x: i32, y: i32, text: &str, c: Color, alpha: u32) -> Rect {
        let b = s.bounds();
        self.draw_clipped(s, x, y, text, c, alpha, b)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    extern crate std;
    use std::vec;
    use std::vec::Vec;

    /// A tiny two-glyph atlas: '?' (2x2, advance 3) and 'A' (1x3, advance 2).
    fn atlas() -> Vec<u8> {
        let mut v = Vec::new();
        v.extend_from_slice(b"OSXP");
        for x in [1u32, 4, 3, 2] {
            v.extend_from_slice(&x.to_le_bytes());
        }
        for (cp, left, top, w, h, adv) in [('?' as u32, 0i16, 0i16, 2u16, 2u16, 3u16), ('A' as u32, 1, 1, 1, 3, 2)] {
            v.extend_from_slice(&cp.to_le_bytes());
            v.extend_from_slice(&left.to_le_bytes());
            v.extend_from_slice(&top.to_le_bytes());
            v.extend_from_slice(&w.to_le_bytes());
            v.extend_from_slice(&h.to_le_bytes());
            v.extend_from_slice(&adv.to_le_bytes());
            v.extend_from_slice(&0u16.to_le_bytes());
        }
        v.extend_from_slice(&0u32.to_le_bytes());
        v.extend_from_slice(&4u32.to_le_bytes());
        v.extend_from_slice(&[255, 255, 255, 255, 255, 128, 255]);
        v
    }

    #[test]
    fn parses_and_measures() {
        let bytes = atlas();
        let f = PropFont::parse(&bytes).unwrap();
        assert_eq!((f.line_height(), f.ascent()), (4, 3));
        assert_eq!(f.measure("AA?"), 7);
        assert_eq!(f.measure("Z"), 3, "missing glyphs fall back to '?'");
        assert!(f.has('A') && !f.has('B'));
        assert_eq!(f.glyph('A').coverage, &[255, 128, 255]);
        assert_eq!(f.hit("AAA", 0), 0);
        assert_eq!(f.hit("AAA", 1), 1);
        assert_eq!(f.hit("AAA", 3), 2);
        assert_eq!(f.hit("AAA", 100), 3);
    }

    #[test]
    fn draws_with_bearings_and_clips() {
        let bytes = atlas();
        let f = PropFont::parse(&bytes).unwrap();
        let mut buf = vec![0u32; 8 * 6];
        let mut s = Surface::new(&mut buf, 8, 6, 8).unwrap();
        f.draw(&mut s, 2, 1, "A", 0xFFFFFF, 255);
        // left 1, top 1: column x = 3, rows y = 2..5
        assert_eq!(s.get(3, 2), Some(0xFFFFFF));
        assert_eq!(s.get(3, 4), Some(0xFFFFFF));
        assert_ne!(s.get(3, 3), Some(0xFFFFFF), "half coverage blends");
        assert_eq!(s.get(2, 2), Some(0));
        let mut buf = vec![0u32; 8 * 6];
        let mut s = Surface::new(&mut buf, 8, 6, 8).unwrap();
        f.draw_clipped(&mut s, 2, 1, "A", 0xFFFFFF, 255, Rect::new(0, 0, 8, 3));
        assert_eq!(s.get(3, 2), Some(0xFFFFFF));
        assert_eq!(s.get(3, 4), Some(0), "clipped away");
        // Drawing far off-surface must not panic.
        f.draw(&mut s, -100, -100, "AAAA", 1, 255);
        f.draw(&mut s, i32::MAX - 10, 0, "A", 1, 255);
    }

    #[test]
    fn ellipsizes() {
        let bytes = atlas();
        let f = PropFont::parse(&bytes).unwrap();
        assert_eq!(f.ellipsize("AA", 4), ("AA", false));
        // '…' falls back to '?' (3 px): budget 5 - 3 = 2 -> one 'A'.
        assert_eq!(f.ellipsize("AAAA", 5), ("A", true));
    }

    #[test]
    fn rejects_malformed_atlases() {
        let good = atlas();
        assert!(PropFont::parse(&good[..10]).is_err());
        assert!(PropFont::parse(&good[..good.len() - 1]).is_err(), "coverage cut short");
        let mut bad = good.clone();
        bad[16..20].copy_from_slice(&0u32.to_le_bytes());
        assert_eq!(PropFont::parse(&bad).err(), Some(AssetError::BadDimensions));
        let mut bad = good.clone();
        // Unsorted code points.
        bad[20 + 16..20 + 20].copy_from_slice(&('!' as u32).to_le_bytes());
        assert_eq!(PropFont::parse(&bad).err(), Some(AssetError::BadDimensions));
        let mut bad = good.clone();
        bad[0] = b'X';
        assert_eq!(PropFont::parse(&bad).err(), Some(AssetError::BadMagic));
        for i in 0..good.len() {
            let mut m = good.clone();
            m[i] ^= 0xFF;
            if let Ok(f) = PropFont::parse(&m) {
                let mut buf = vec![0u32; 16 * 16];
                let mut s = Surface::new(&mut buf, 16, 16, 16).unwrap();
                f.draw(&mut s, 0, 0, "A?Z", 0xFFFFFF, 255);
            }
        }
    }
}
